<h2 class="mb-3">Nạp tiền / Bán combo</h2><div class="row g-4"><div class="col-md-6"><div class="card p-3"><h5>Nạp tiền</h5><form method="post" action="<?= htmlspecialchars(BASE_URL . '/wallet/topup') ?>"><label class="form-label">Tài khoản</label><select class="form-select mb-3" name="account_id" required><?php foreach ($accounts as $account): ?><option value="<?= (int) $account['id'] ?>"><?= htmlspecialchars($account['username'] . ' - ' . $account['display_name']) ?> (<?= number_format((float) $account['balance'], 0, ',', '.') ?>đ)</option><?php endforeach; ?></select><label class="form-label">Số tiền</label><input class="form-control mb-3" type="number" min="1000" step="1000" name="amount" required><button class="btn btn-success">Nạp tiền</button></form></div></div><div class="col-md-6"><div class="card p-3"><h5>Bán combo</h5><form method="post" action="<?= htmlspecialchars(BASE_URL . '/wallet/buy-combo') ?>"><label class="form-label">Tài khoản</label><select class="form-select mb-3" name="account_id" required><?php foreach ($accounts as $account): ?><option value="<?= (int) $account['id'] ?>"><?= htmlspecialchars($account['username'] . ' - ' . $account['display_name']) ?></option><?php endforeach; ?></select><label class="form-label">Combo</label><select class="form-select mb-3" name="combo_id" required><?php foreach ($combos as $combo): ?><option value="<?= (int) $combo['id'] ?>"><?= htmlspecialchars($combo['name']) ?> - <?= number_format((float) $combo['price'], 0, ',', '.') ?>đ</option><?php endforeach; ?></select><button class="btn btn-primary">Bán combo</button></form></div></div></div>
